<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('hunts.view');$q=trim((string)input('q'));$status=strtoupper(trim((string)input('status')));$where=[];$params=[];if($q!==''){$where[]='(h.title LIKE ? OR h.slug LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if(in_array($status,['DRAFT','ACTIVE','INACTIVE','ENDED'],true)){$where[]='h.status=?';$params[]=$status;}$sql=$where?' WHERE '.implode(' AND ',$where):'';$s=db()->prepare('SELECT h.*,(SELECT COUNT(*) FROM hunt_locations WHERE hunt_id=h.id) locations,(SELECT COUNT(*) FROM hunt_user_activations WHERE hunt_id=h.id) activations,(SELECT COUNT(*) FROM hunt_scans WHERE hunt_id=h.id) scans FROM hunts h'.$sql.' ORDER BY h.id DESC');$s->execute($params);$hunts=$s->fetchAll();$pageTitle='Hunts';$pageSubtitle='Configure adventure campaigns and their controlled lifecycle';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><div class="panel-head"><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search hunts"><select name="status"><option value="">All statuses</option><?php foreach(['DRAFT','ACTIVE','INACTIVE','ENDED'] as $v):?><option <?=$status===$v?'selected':''?>><?=e($v)?></option><?php endforeach?></select><button class="btn">Filter</button></form><?php if(can('hunts.manage')):?><a class="btn" href="<?=e(app_url('/admin/hunts/edit.php'))?>">New hunt</a><?php endif?></div><div class="table-wrap"><table><thead><tr><th>Hunt</th><th>Dates</th><th>Fee</th><th>Reward range</th><th>Locations</th><th>Activations</th><th>Scans</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($hunts as $h):?><tr><td><strong><?=e($h['title'])?></strong><br><small><?=e($h['slug'])?></small></td><td><?=e($h['start_at'])?><br><?=e($h['end_at'])?></td><td><?=money($h['activation_fee'])?></td><td><?=money($h['reward_min'])?>–<?=money($h['reward_max'])?></td><td><?=e($h['locations'])?></td><td><?=e($h['activations'])?></td><td><?=e($h['scans'])?></td><td><span class="badge <?=strtolower(e($h['status']))?>"><?=e($h['status'])?></span></td><td class="actions"><a class="btn small secondary" href="<?=e(app_url('/admin/hunts/manage.php?id='.$h['id']))?>">Manage</a><?php if(can('hunts.manage')):?><a class="btn small" href="<?=e(app_url('/admin/hunts/edit.php?id='.$h['id']))?>">Edit</a><?php endif?></td></tr><?php endforeach?></tbody></table><?php if(!$hunts):?><div class="empty">No hunts match these filters.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
